contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(uint256 sendAmount) public {
        // precondition: this contract has enough balance to forward
        require(address(this).balance >= sendAmount);

        // record owner and balances before
        address owner = c.owner();
        uint256 ownerBefore = owner.balance;
        uint256 contractBefore = address(c).balance;

        // CALL under test: send ETH to c.go()
        c.go{value: sendAmount}();

        // After successful original behavior, c should forward all its balance to owner
        // So c's balance should be equal to contractBefore (unchanged) + sendAmount then cleared to 0
        // We assert owner gained exactly sendAmount (no loss due to ignored failure)
        uint256 ownerAfter = owner.balance;
        assert(ownerAfter - ownerBefore == sendAmount);
    }

    // Allow this test contract to receive ETH to fund calls
    receive() external payable {}
}

