pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz amount and use an adversarial owner contract to observe difference
    function testFuzz_property(uint256 amount) public {
        // keep amount reasonable but wide; allow zero too
        amount = bound(amount, 0, 1 ether);

        // Deploy a helper that will make sending to owner fail (reverting receive)
        ReverterOwner badOwner = new ReverterOwner();

        // Replace c.owner by deploying a fresh C whose owner is msg.sender; we cannot change owner of existing c.
        // To route the contract to use the adversarial owner, we will deploy a proxy-like wrapper contract
        // that forwards go() calls but uses the target address hardcoded in C. However the reference C sets owner
        // at construction to msg.sender; so to make c.owner == badOwner we must deploy C from badOwner.

        // Deploy C from badOwner so its owner is badOwner
        vm.prank(address(badOwner));
        C c2 = new C();

        // Fund the caller EOA to send value into c2.go
        address caller = address(0xBEEF);
        vm.deal(caller, amount + 1 ether);

        // Now call go on c2, sending amount and having the first external call target (hardcoded) succeed or fail
        // The first call goes to the fixed target in C; that address is an EOA in tests and low-level call will succeed.
        vm.prank(caller);
        // Call and catch to continue even if go reverts; we only care about final balance of c2
        bool ok;
        try c2.go{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for the correct contract using transfer, the contract should end with zero balance
        // after go() completes irrespective of amount. We assert that address(c2).balance == 0.
        // This holds for the reference for all inputs. The mutant that uses call{value: balance} and checks returned
        // bool can be affected by the owner being a reverting contract; for some inputs the mutant will leave funds
        // in c2, making this assertion fail.
        assertTrue(address(c2).balance == 0);
    }
}

