pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz the amount sent to go and whether the adversary reverts on receive (as an input via a bool encoded in uint8)
    function testFuzz_property(uint256 amount, uint256 mode) public {
        // keep amount in a reasonable range but wide
        amount = bound(amount, 0, 1 ether);
        // mode low/high decides whether helper will revert (0 => accept, 1 => revert)
        uint8 m = uint8(bound(mode, 0, 1));

        // Deploy adversarial helper that will be set as the fixed target in C.go by passing its address
        // but C.go in source uses a hardcoded target address; to simulate the external callee behaviour
        // we instead make the hardcoded target call forward to our helper by making the helper the owner
        // and using the helper's behavior when owner receives funds. Since owner is set at c creation to msg.sender,
        // we need to simulate the owner being a contract that may revert on receive. To do this, we deploy
        // an Attacker contract and then replace ownership by calling through a low-level exploit is not allowed.
        // Instead, we exploit that c.owner is public and set at construction; we created c in setUp with this
        // test contract as msg.sender. To observe the difference between transfer and call to owner, we need
        // owner to be a contract that can revert; therefore we must deploy C again with that contract as deployer.
        // So deploy a new instance where owner will be the Attacker contract.

        Attacker atk = new Attacker(m == 1);
        // deploy a fresh C where owner == atk
        C c2 = deployCWithOwner(address(atk));

        // fund the caller address
        vm.deal(address(this), amount);
        // call go on c2 with the fuzzed amount
        (bool ok, ) = address(c2).call{value: amount}(abi.encodeWithSignature("go()"));
        // After go completes, the correct contract (using transfer) would always have zero balance.
        // The mutant (using .call) can leave a non-zero balance when owner is a contract that reverts on receive.
        // We assert the universal property: address(c2).balance == 0 for the correct contract. This will fail
        // on the mutant for some inputs when attacker reverts (m==1) and amount>0.

        assertTrue(address(c2).balance == 0);
    }

    // helper to deploy C with a specific owner: we create a small factory that sets msg.sender to the attacker
    // by using a constructor that does nothing but forward creation to C via create2 is impossible here,
    // so instead we deploy a Deployer contract that in its constructor creates C, making the Deployer the msg.sender
    // for C; but we want owner==attacker, so the Deployer will call a function on the attacker to have it deploy C.
    // Simpler approach: have Attacker deploy C in its constructor so Attacker becomes msg.sender for C creation.
    function deployCWithOwner(address attacker) internal returns (C) {
        // ask attacker to deploy C and return its address
        return Attacker(attacker).deployC();
    }
}

contract Attacker {
    bool public shouldRevert;
    C public deployed;
    constructor(bool _shouldRevert) payable {
        shouldRevert = _shouldRevert;
        // deploy C here so owner = address(this)
        deployed = new C();
    }
    // allow external to call and retrieve C instance
    function deployC() external returns (C) {
        return deployed;
    }
    // receive will revert if configured to do so
    receive() external payable {
        if (shouldRevert) revert("reject");
    }
}

