}

// helper that deploys C so that its owner is msg.sender (the deployer will be the provided owner via create2-like pattern)
contract Deployer {
    function deployCWithOwner(address owner) external returns (address payable) {
        // deploy a factory that will deploy C with msg.sender as owner: we need to deploy C so that owner == msg.sender
        // Achieve by having this contract (Deployer) create a small wrapper that in its constructor deploys C; that wrapper's deployer is this function caller
        Wrapper w = new Wrapper();
        // Now have the wrapper deploy C with msg.sender == wrapper, but we want owner to be the external provided owner; so instead
        // call wrapper.createCWithOwner(owner) which will deploy a C from wrapper but with constructor setting owner to wrapper — impossible.
        // Simpler: deploy C from the desired owner by having the owner contract perform the deployment. So call the owner's deployer function.
        RevertingOwner(payable(owner)).deployC_byMe();
        return payable(address(0));
    }
}

contract Wrapper {}

contract RevertingOwner {
    address payable public lastDeployed;
    // this function deploys C so that owner==address(this)
    function deployC_byMe() external returns (address) {
        C c = new C();
        lastDeployed = payable(address(c));
        return address(c);
    }
    receive() external payable {
        revert("nope");
    }
}

