contract InvMutTest is Test {
    C c;
    // We will deploy a helper that accepts ETH when called so that in the reference
    // the low-level call to target forwards value and succeeds consuming the sent ETH,
    // whereas the mutant calling with value 0 will leave the ETH in C and then transfer
    // the contract balance to owner, causing different final balances.
    AcceptingTarget target;

    function setUp() public { 
        c = new C();
        target = new AcceptingTarget();
    }

    // Fuzz the sender and amount. For the reference contract, after calling go with any amount
    // the contract should forward that amount to the target and then transfer remaining balance (0)
    // to owner, leaving address(c).balance == 0. The mutant that calls target with value 0 will
    // leave the sent amount in c and end up transferring it to owner (or otherwise change balances),
    // so address(c).balance may differ (>0) for some inputs. We assert that address(c).balance == 0
    // which holds for the reference for all inputs, but the mutant will fail for some inputs.
    function testFuzz_property(address sender, uint256 amount) public {
        // keep amount within reasonable gas/ether bounds
        amount = bound(amount, 0, 10 ether);
        // avoid zero-address sender for clarity
        vm.assume(sender != address(0));

        // Fund the sender so it can send ETH
        vm.deal(sender, amount);

        // The reference's target address inside C is hard-coded; we need to ensure that
        // the call to that address actually hits our AcceptingTarget. We cannot change
        // C's code here, but we can simulate the externally visible behavior by invoking
        // go via a pre-funded attacker that sends ETH to C and since the reference uses a
        // fixed target literal, to actually make the call go to our AcceptingTarget we
        // adjust test by deploying AcceptingTarget at that same address via create2.
        // However foundry tests cannot easily create at arbitrary hard-coded addresses.
        // Instead, we will rely on the fact that the meaningful difference is whether
        // C forwards msg.value to its target call; we can observe the remaining balance of C
        // after go to detect if the forward happened. We will invoke go with the fuzzed sender
        // and amount and assert that address(c).balance == 0 for the reference contract.

        vm.prank(sender);
        // call go with value `amount`
        // Note: go's internal target is fixed; the mutant differs only by value forwarded to target.
        // For the reference, ETH should be forwarded out and then owner gets balance, leaving 0.
        (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSignature("go()"));
        // we accept both success and revert as admissible but the reference should not revert
        // since its low-level call's return is checked; so require the call succeeded.
        // If it reverted, the property fails for this input and the test will fail which is fine
        // because the reference should succeed for all inputs in normal conditions.
        require(ok, "c.go call reverted unexpectedly");

        // Exactly one assertion: the reference contract should always have zero balance after go()
        // (it forwards received ETH to the target and then transfers remaining balance to owner).
        assertTrue(address(c).balance == 0);
    }
}

